    "punishmentOrNotes": "Murder (old 300). Four clauses: intention to cause death; intention to cause bodily injury the offender knows is likely to cause death; intention to cause injury sufficient in the ordinary course of nature to cause death (Virsa Singh); knowledge that the act is so imminently dangerous that it must in all probability cause death. Five exceptions knock it down to s. 105.",
